     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinAllExceptUsuario(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        // $criteria->getDbName() will return the same object if not set to another value
        // so == check is okay and faster
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(TaskInstancePeer::DATABASE_NAME);
        }

        TaskInstancePeer::addSelectColumns($criteria);
        $startcol2 = TaskInstancePeer::NUM_HYDRATE_COLUMNS;

        WorkflowInstancePeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + WorkflowInstancePeer::NUM_HYDRATE_COLUMNS;

        TaskDefinitionPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + TaskDefinitionPeer::NUM_HYDRATE_COLUMNS;

        TaskinstanceStatusPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + TaskinstanceStatusPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(TaskInstancePeer::WORKFLOWINSTANCE_ID, WorkflowInstancePeer::WORKFLOWINSTANCE_ID, $join_behavior);

        $criteria->addJoin(TaskInstancePeer::TASKDEFINITION_ID, TaskDefinitionPeer::TASKDEFINITION_ID, $join_behavior);

        $criteria->addJoin(TaskInstancePeer::TASKINSTANCESTATUS_ID, TaskinstanceStatusPeer::TASKINSTANCESTATUS_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseTaskInstancePeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = TaskInstancePeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = TaskInstancePeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = TaskInstancePeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                TaskInstancePeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined WorkflowInstance rows

                $key2 = WorkflowInstancePeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = WorkflowInstancePeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = WorkflowInstancePeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    WorkflowInstancePeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (TaskInstance) to the collection in $obj2 (WorkflowInstance)
                $obj2->addTaskInstance($obj1);

            } // if joined row is not null

                // Add objects for joined TaskDefinition rows

                $key3 = TaskDefinitionPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = TaskDefinitionPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = TaskDefinitionPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    TaskDefinitionPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (TaskInstance) to the collection in $obj3 (TaskDefinition)
                $obj3->addTaskInstance($obj1);

            } // if joined row is not null

                // Add objects for joined TaskinstanceStatus rows

                $key4 = TaskinstanceStatusPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = TaskinstanceStatusPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = TaskinstanceStatusPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    TaskinstanceStatusPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (TaskInstance) to the collection in $obj4 (TaskinstanceStatus)
                $obj4->addTaskInstance($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }

